public sealed class MoonBitArray<T>
{
    public T[] Buffer;
    public int Length;
    public int Count => Length;

    public MoonBitArray()
    {
        Buffer = [];
        Length = 0;
    }

    public MoonBitArray(int capacity)
    {
        Buffer = new T[capacity];
        Length = 0;
    }

    public MoonBitArray(ReadOnlySpan<T> items)
    {
        Buffer = items.ToArray();
        Length = Buffer.Length;
    }

    public MoonBitArray(T[] buffer)
    {
        Buffer = buffer;
        Length = buffer.Length;
    }

    public MoonBitArray(T[] buffer, int length)
    {
        Buffer = buffer;
        Length = length;
    }

    public T this[int index] { get => MoonBitArray.At(this, index); set => MoonBitArray.Set(this, index, value); }

    public ReadOnlySpan<T> AsSpan() => Buffer.AsSpan(0, Length);

    public static MoonBitArray<T> MakeUninit(int length) => new(new T[length], length);

    public static MoonBitArray<T> operator +(MoonBitArray<T> left, MoonBitArray<T> right) =>
        MoonBitArray.Concat(left, right);

    public static MoonBitArray<T> operator +(MoonBitArray<T> left, MoonBitArrayView<T> right) =>
        MoonBitArray.Concat(left, right);

    public static MoonBitArray<T> operator +(MoonBitArray<T> left, MoonBitIter<T> right) =>
        MoonBitArray.Concat(left, right);

}

public static class MoonBitArray
{
    public static MoonBitArray<T> FromSpan<T>(ReadOnlySpan<T> items) => new(items);
    public static MoonBitArray<T> FromArray<T>(T[] items) => new(items.AsSpan());
    public static bool IsEmpty<T>(MoonBitArray<T> array) => array.Length == 0;

    public static MoonBitArray<T> Concat<T>(MoonBitArray<T> left, MoonBitArray<T> right)
    {
        var result = new MoonBitArray<T>(new T[left.Length + right.Length], left.Length + right.Length);
        left.AsSpan().CopyTo(result.Buffer);
        right.AsSpan().CopyTo(result.Buffer.AsSpan(left.Length));
        return result;
    }

    public static MoonBitArray<T> Concat<T>(MoonBitArray<T> left, MoonBitArrayView<T> right)
    {
        var result = new MoonBitArray<T>(new T[left.Length + right.Length], left.Length + right.Length);
        left.AsSpan().CopyTo(result.Buffer);
        right.AsSpan().CopyTo(result.Buffer.AsSpan(left.Length));
        return result;
    }

    public static MoonBitArray<T> Concat<T>(MoonBitArray<T> left, MoonBitIter<T> right) =>
        Concat(left, right.ToArray());

    public static T At<T>(MoonBitArray<T> array, int index)
    {
        var len = array.Length;
        if (index < 0 || index >= len)
        {
            throw new MoonBitPanic("panic");
        }

        return array.Buffer[index];
    }

    public static T UnsafeGet<T>(MoonBitArray<T> array, int index) => array.Buffer[index];

    public static MoonBitOption<T> Get<T>(MoonBitArray<T> array, int index)
    {
        var len = array.Length;
        return index >= 0 && index < len ? MoonBitOption<T>.Some(array.Buffer[index]) : MoonBitOption<T>.None();
    }

    public static MoonBitUnit Set<T>(MoonBitArray<T> array, int index, T value)
    {
        var len = array.Length;
        if (index < 0 || index >= len)
        {
            throw new MoonBitPanic("panic");
        }

        array.Buffer[index] = value;
        return MoonBitUnit.Value;
    }

    public static MoonBitUnit UnsafeSet<T>(MoonBitArray<T> array, int index, T value)
    {
        array.Buffer[index] = value;
        return MoonBitUnit.Value;
    }

    public static MoonBitUnit Push<T>(MoonBitArray<T> array, T item)
    {
        EnsureCapacity(array, array.Length + 1);
        array.Buffer[array.Length] = item;
        array.Length += 1;
        return MoonBitUnit.Value;
    }

    public static MoonBitOption<T> Pop<T>(MoonBitArray<T> array)
    {
        if (array.Length == 0)
        {
            return MoonBitOption<T>.None();
        }

        var index = array.Length - 1;
        var item = array.Buffer[index];
        array.Buffer[index] = default!;
        array.Length = index;
        return MoonBitOption<T>.Some(item);
    }

    public static MoonBitArray<T> Copy<T>(MoonBitArray<T> array)
    {
        var copy = new T[array.Length];
        System.Array.Copy(array.Buffer, copy, array.Length);
        return new MoonBitArray<T>(copy, array.Length);
    }

    public static MoonBitUnit ReserveCapacity<T>(MoonBitArray<T> array, int capacity)
    {
        EnsureCapacity(array, capacity);
        return MoonBitUnit.Value;
    }

    public static MoonBitUnit ShrinkToFit<T>(MoonBitArray<T> array)
    {
        if (array.Buffer.Length != array.Length)
        {
            System.Array.Resize(ref array.Buffer, array.Length);
        }

        return MoonBitUnit.Value;
    }

    public static MoonBitUnit UnsafeTruncateToLength<T>(MoonBitArray<T> array, int length)
    {
        if (length < array.Length)
        {
            System.Array.Clear(array.Buffer, length, array.Length - length);
        }

        array.Length = length;
        return MoonBitUnit.Value;
    }

    public static string JoinStrings(MoonBitArray<string> array, string separator)
    {
        if (array.Length == 0)
        {
            return "";
        }

        var builder = new System.Text.StringBuilder(array.Buffer[0]);
        for (var i = 1; i < array.Length; i++)
        {
            builder.Append(separator);
            builder.Append(array.Buffer[i]);
        }

        return builder.ToString();
    }

    private static void EnsureCapacity<T>(MoonBitArray<T> array, int capacity)
    {
        if (array.Buffer.Length >= capacity)
        {
            return;
        }

        var next = array.Buffer.Length == 0 ? 8 : array.Buffer.Length * 2;
        while (next < capacity)
        {
            next *= 2;
        }

        System.Array.Resize(ref array.Buffer, next);
    }
}

public static class MoonBitIterArrayExtensions
{
    public static MoonBitArray<T> ToArray<T>(this MoonBitIter<T> iter)
    {
        var result = new MoonBitArray<T>();
        while (true)
        {
            var item = iter.Next();
            if (item.IsNone)
            {
                return result;
            }

            MoonBitArray.Push(result, item.Value);
        }
    }
}

public static class MoonBitArrayViewBounds
{
    public static int CheckedOffset(int startOffset, int length, int index)
    {
        if ((uint)index >= (uint)length)
        {
            throw new MoonBitPanic("index out of bounds");
        }

        return startOffset + index;
    }

    public static (int Start, int Length) ValidateRange(int length, int start, int? end)
    {
        if (start < 0)
        {
            start = length + start;
        }

        var actualEnd = end ?? length;
        if (actualEnd < 0)
        {
            actualEnd = length + actualEnd;
        }

        if (start < 0 || actualEnd < start || actualEnd > length)
        {
            throw new MoonBitPanic("View index out of bounds");
        }

        return (start, actualEnd - start);
    }

    public static void ValidateAbsoluteRange(int bufferLength, int start, int length)
    {
        if (start < 0 || length < 0 || start + length > bufferLength)
        {
            throw new MoonBitPanic("View index out of bounds");
        }
    }
}

public readonly struct MoonBitArrayView<T>
{
    public T[] Buffer { get; }
    public int StartOffset { get; }

    public MoonBitArrayView(MoonBitArray<T> array, int start = 0, int? end = null)
    {
        Buffer = array.Buffer;
        (StartOffset, Length) = MoonBitArrayViewBounds.ValidateRange(array.Length, start, end);
    }

    public MoonBitArrayView(T[] array, int start = 0, int? end = null)
    {
        Buffer = array;
        (StartOffset, Length) = MoonBitArrayViewBounds.ValidateRange(array.Length, start, end);
    }

    private MoonBitArrayView(T[] buffer, int start, int length, bool _)
    {
        Buffer = buffer;
        StartOffset = start;
        Length = length;
    }

    public int Length { get; }

    public ReadOnlySpan<T> AsSpan() => Buffer.AsSpan(StartOffset, Length);

    public T this[int index] => SourceGet(CheckedOffset(index));
    public object? GetObject(int index) => this[index];

    public static implicit operator MoonBitArrayView<T>(MoonBitArray<T> array) => new(array);
    public static implicit operator MoonBitArrayView<T>(T[] array) => new(array);
    public static implicit operator MoonBitArrayView<T>(MoonBitMutArrayView<T> view) =>
        Make(view.Buffer, view.StartOffset, view.Length);

    public static MoonBitArrayView<T> Make(T[] buffer, int start, int length)
    {
        MoonBitArrayViewBounds.ValidateAbsoluteRange(buffer.Length, start, length);
        return new MoonBitArrayView<T>(buffer, start, length, true);
    }

    private T SourceGet(int index) => Buffer[index];
    private int CheckedOffset(int index) =>
        MoonBitArrayViewBounds.CheckedOffset(StartOffset, Length, index);
}

