public readonly struct MoonBitBytesView
{
    public MoonBitBytesView(byte[] buffer, int start, int length)
    {
        if (start < 0 || length < 0 || start + length > buffer.Length)
        {
            throw new MoonBitPanic("View index out of bounds");
        }

        Buffer = buffer;
        StartOffset = start;
        Length = length;
    }

    public byte[] Buffer { get; }
    public int StartOffset { get; }
    public int Length { get; }
    public ReadOnlySpan<byte> Span => Buffer.AsSpan(StartOffset, Length);
    public byte this[int index] => Buffer[CheckedOffset(index)];

    private int CheckedOffset(int index)
    {
        if ((uint)index >= (uint)Length)
        {
            throw new MoonBitPanic($"index out of bounds: the len is from 0 to {Length} but the index is {index}");
        }

        return StartOffset + index;
    }
}

