public static class MoonBitBitString
{
    public static ulong ExtractUnsigned(ReadOnlySpan<byte> data, int bitOffset, int width, bool littleEndian)
    {
        if ((uint)width > 64U || width == 0)
        {
            throw new MoonBitPanic("invalid bitstring width");
        }

        if (littleEndian)
        {
            if ((width & 7) != 0)
            {
                throw new MoonBitPanic("little-endian bitstring width must be byte-aligned");
            }

            ulong value = 0;
            for (var i = 0; i < width / 8; i++)
            {
                value |= (ulong)data[(bitOffset / 8) + i] << (i * 8);
            }

            return value;
        }

        ulong result = 0;
        for (var i = 0; i < width; i++)
        {
            var absolute = bitOffset + i;
            var b = data[absolute / 8];
            var bit = (b >> (7 - (absolute & 7))) & 1;
            result = (result << 1) | (uint)bit;
        }

        return result;
    }

    public static long ExtractSigned(ReadOnlySpan<byte> data, int bitOffset, int width, bool littleEndian)
    {
        var unsigned = ExtractUnsigned(data, bitOffset, width, littleEndian);
        var signBit = 1UL << (width - 1);
        if ((unsigned & signBit) == 0)
        {
            return (long)unsigned;
        }

        return width == 64
            ? unchecked((long)unsigned)
            : (long)(unsigned - (1UL << width));
    }
}

public sealed class MoonBitStringBuilder
{
    private readonly System.Text.StringBuilder _builder;
    public MoonBitStringBuilder(int sizeHint = 0)
    {
        _builder = sizeHint > 0 ? new System.Text.StringBuilder(sizeHint) : new System.Text.StringBuilder();
    }

    public static implicit operator Logger(MoonBitStringBuilder builder) =>
        new(builder, MoonBitStringBuilderAsLogger.Instance);

    public MoonBitUnit WriteString(string value)
    {
        _builder.Append(value);
        return MoonBitUnit.Value;
    }

    public MoonBitUnit WriteString(MoonBitStringView value)
    {
        _builder.Append(value.AsSpan());
        return MoonBitUnit.Value;
    }

    public MoonBitUnit WriteChar(int value)
    {
        if(value < 0xFFFF)
        {
            _builder.Append((char)value);
        }
        else
        {
            var rune = new System.Text.Rune(value);
            Span<char> buffer = stackalloc char[4];
            var length = rune.EncodeToUtf16(buffer);
            _builder.Append(buffer.Slice(0, length));
        }
        return MoonBitUnit.Value;
    }

    public MoonBitUnit WriteSubstring(string value, int start, int length)
    {
        _builder.Append(value, start, length);
        return MoonBitUnit.Value;
    }

    public MoonBitUnit Reset()
    {
        _builder.Clear();
        return MoonBitUnit.Value;
    }

    public override string ToString() => _builder.ToString();
}

public static class MoonBitStringExtensions
{
    public static MoonBitStringView View(this string value) => new(value, 0, value.Length);
    public static MoonBitStringView View(this string value, int start) => value.View(start, value.Length);
    public static MoonBitStringView View(this string value, int start, int end)
    {
        if (start < 0)
        {
            start = value.Length + start;
        }

        if (end < 0)
        {
            end = value.Length + end;
        }

        return new(value, start, end);
    }

    public static bool ContainsOrdinal(this string value, string part) => value.Contains(part, StringComparison.Ordinal);
    public static bool HasPrefix(this string value, string prefix) => value.StartsWith(prefix, StringComparison.Ordinal);
    public static bool HasSuffix(this string value, string suffix) => value.EndsWith(suffix, StringComparison.Ordinal);
    public static bool IsEmpty(this string value) => value.Length == 0;
    public static string ReplaceAll(this string value, string oldValue, string newValue) => value.Replace(oldValue, newValue, StringComparison.Ordinal);
    public static MoonBitStringView TrimMoonBit(this string value) => value.View().Trim();
    public static string ToLowerMoonBit(this string value) => value.ToLowerInvariant();
    public static MoonBitOption<MoonBitStringView> BeforeMoonBit(this string value, string marker) => value.View().Before(marker);
    public static MoonBitOption<MoonBitStringView> AfterMoonBit(this string value, string marker) => value.View().After(marker);
    public static MoonBitOption<(MoonBitStringView, MoonBitStringView)> SplitOnceMoonBit(this string value, string marker) => value.View().SplitOnce(marker);
    public static MoonBitIter<MoonBitStringView> SplitMoonBit(this string value, MoonBitStringView separator) => value.View().Split(separator);
}

public readonly record struct MoonBitStringView(string Data, int Start, int End)
{
    public static implicit operator MoonBitStringView(string value) => new(value, 0, value.Length);
    public int Length => End - Start;
    public int StartOffset => Start;
    public string Source => Data;
    public ReadOnlySpan<char> AsSpan() => Data.AsSpan(Start, Length);

    public ushort this[int index] => (ushort)Data[Start + index];
    public MoonBitStringView Sub(int startOffset, int? endOffset = null)
    {
        var end = endOffset ?? Length;
        if (startOffset < 0)
        {
            startOffset = Length + startOffset;
        }

        if (end < 0)
        {
            end = Length + end;
        }

        if (startOffset < 0 || startOffset > end || end > Length)
        {
            throw new ArgumentOutOfRangeException(nameof(startOffset), "Invalid index for View");
        }

        return new MoonBitStringView(Data, Start + startOffset, Start + end);
    }

    public string ToOwned() => ToString();
    public override string ToString() => Data.Substring(Start, Length);
    public static bool operator ==(MoonBitStringView left, string right) => right is not null && left.AsSpan().SequenceEqual(right.AsSpan());
    public static bool operator !=(MoonBitStringView left, string right) => !(left == right);
    public static bool operator ==(string left, MoonBitStringView right) => left is not null && left.AsSpan().SequenceEqual(right.AsSpan());
    public static bool operator !=(string left, MoonBitStringView right) => !(left == right);
    public bool ContainsOrdinal(string part) => AsSpan().Contains(part.AsSpan(), StringComparison.Ordinal);
    public bool HasPrefix(string prefix) => AsSpan().StartsWith(prefix.AsSpan(), StringComparison.Ordinal);
    public bool HasSuffix(string suffix) => AsSpan().EndsWith(suffix.AsSpan(), StringComparison.Ordinal);
    public MoonBitStringView Trim()
    {
        var start = Start;
        var end = End;
        while (start < end && char.IsWhiteSpace(Data[start]))
        {
            start++;
        }

        while (end > start && char.IsWhiteSpace(Data[end - 1]))
        {
            end--;
        }

        return new MoonBitStringView(Data, start, end);
    }

    public MoonBitOption<MoonBitStringView> Before(string marker)
    {
        var index = Data.IndexOf(marker, Start, Length, StringComparison.Ordinal);
        return index < 0 ? MoonBitOption<MoonBitStringView>.None() : MoonBitOption<MoonBitStringView>.Some(new MoonBitStringView(Data, Start, index));
    }

    public MoonBitOption<MoonBitStringView> After(string marker)
    {
        var index = Data.IndexOf(marker, Start, Length, StringComparison.Ordinal);
        return index < 0 ? MoonBitOption<MoonBitStringView>.None() : MoonBitOption<MoonBitStringView>.Some(new MoonBitStringView(Data, index + marker.Length, End));
    }

    public MoonBitOption<(MoonBitStringView, MoonBitStringView)> SplitOnce(string marker)
    {
        var index = Data.IndexOf(marker, Start, Length, StringComparison.Ordinal);
        return index < 0 ? MoonBitOption<(MoonBitStringView, MoonBitStringView)>.None() : MoonBitOption<(MoonBitStringView, MoonBitStringView)>.Some((new MoonBitStringView(Data, Start, index), new MoonBitStringView(Data, index + marker.Length, End)));
    }

    public MoonBitIter<MoonBitStringView> Split(MoonBitStringView separator)
    {
        var source = this;
        var remaining = source;
        var index = 0;
        if (separator.Length == 0)
        {
            return new MoonBitIter<MoonBitStringView>(() =>
            {
                if (index >= source.Length)
                {
                    return MoonBitOption<MoonBitStringView>.None();
                }

                var item = source.Sub(index, index + 1);
                index += 1;
                return MoonBitOption<MoonBitStringView>.Some(item);
            });
        }

        return new MoonBitIter<MoonBitStringView>(() =>
        {
            if (remaining.Start > remaining.End)
            {
                return MoonBitOption<MoonBitStringView>.None();
            }

            var found = remaining.AsSpan().IndexOf(separator.AsSpan(), StringComparison.Ordinal);
            if (found < 0)
            {
                var last = remaining;
                remaining = new MoonBitStringView(source.Data, source.End + 1, source.End);
                return MoonBitOption<MoonBitStringView>.Some(last);
            }

            var item = remaining.Sub(0, found);
            remaining = remaining.Sub(found + separator.Length);
            return MoonBitOption<MoonBitStringView>.Some(item);
        });
    }
}

